import re

from robot.libraries.BuiltIn import BuiltIn

from taf.ul.bts_components import Smod

from taf.ul.kpi_selector.utilities.connections_keywords import get_details_to_login_from_init
from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output, log_env_state, log_suppression
from taf.ul.kpi_selector.utilities.exceptions import WFTError
from taf.ul.kpi_selector.utilities.wft.remote_api import BuildEndpoint


class WFT(object):

    def __init__(self):
        tl = BuiltIn().get_variable_value('${tl}')
        self.bts_type = "GNB" if tl.gnbs else "ENB"

    @log_input_and_output
    def get_scm_flag(self, rfsw):
        """
        Gets scm flag.

        :param rfsw: radio software.
                E.g. input: 'FRM51.03.R13'
        :type rfsw: str
        :return: scm flag.
                E.g. output: 'rel5.1'
        :rtype: str
        :raise WFTError when details for given radio software will not be found.
        """
        version = self._get_valid_sw_version()
        rfsw_build = self._get_rfsw_project_info(rfsw)

        if self._check_if_matches_pattern_for_sbts(version):
            build_attributes = BuildEndpoint(
                project=rfsw_build['project'],
                component=rfsw_build['component'],
                version=rfsw_build['version'],
            ).build_attributes()

            return build_attributes['bb_location'].split('/')[-1]

        return rfsw.split('.')[1]

    def _get_rfsw_sub_build(self, rfsw, version):
        sub_builds = self._get_sub_builds_of_sw_package(version)

        for sub_build in sub_builds:
            if sub_build['version'] == rfsw:
                log_env_state("rfsw sub build: {}".format(sub_build))

                return sub_build

        raise WFTError("Sub build with given version: {} does not exist.".format(rfsw))

    @staticmethod
    def _get_rfsw_project_info(rfsw):
        return BuildEndpoint(
            project="",
            component="",
            version="",
        ).get_rfsw_build_project(rfsw)

    def _get_valid_sw_version(self):
        """
        Checks if given version is not a knife or a T1/2 package, and if it is, it gets its baseline SW build
        :return: valid SW build
        :rtype: str
        """
        version = self._get_sw_version()

        if self._check_if_sw_version_is_knife(version):
            try:
                return BuildEndpoint(project="", component="", version=version).get_baseline_sw_build()
            except WFTError:
                log_suppression('Could not get baseline SW version based on given knife {}'.format(version))

        elif self._check_if_sw_version_is_t_package(version):
            return version[:-2]

        return version

    @staticmethod
    @log_input_and_output
    def _get_sub_builds_of_sw_package(version):
        return BuildEndpoint(
            project="5G",
            component="BTS",
            version=version,
        ).sub_builds()

    def _get_sw_version(self):
        smod = Smod()
        try:
            smod.connect_to(*get_details_to_login_from_init("ssh", bts_type=self.bts_type))
            return smod.get_sw_version_from_targetbd()

        finally:
            smod.close_connection()

    @staticmethod
    def _check_if_matches_pattern_for_sbts(version):
        pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_[0-9]{6}(T[1-2])?$'
        return bool(re.match(pattern, version))

    @staticmethod
    def _check_if_sw_version_is_knife(version):
        pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_00'
        return not bool(re.match(pattern, version))

    @staticmethod
    def _check_if_sw_version_is_t_package(version):
        pattern = r".+T[1-2]$"
        return bool(re.match(pattern, version))
